def can_broadcast(a, b):
    """Broadcasting rule: right-to-left align, dims equal or 1."""
    for x, y in zip(a[::-1], b[::-1]):
        if x != y and x != 1 and y != 1:
            return False
    return True

print(can_broadcast((3, 2), (2,)))
print(can_broadcast((3, 2), (3, 1)))
print(can_broadcast((3, 2), (4,)))
print(can_broadcast((3, 1, 4), (4,)))
